declare(strict_types=1);

/**
 * Adds the surface of OCP\Notification\IManager to tests/fixtures/nextcloud-api/<major>.php (issue #26: the Deck
 * assignment defers notification delivery through it). Every other class of the fixture is left as it is.
 *
 * Usage: php tests/fixtures/nextcloud-api/generate-notification-manager.php <major> <tree>
 *
 * <tree> holds lib/public/Notification of the nextcloud/server release named in NextcloudApiUsage::SOURCES for that
 * major (tag v<server>), for example fetched file by file from
 * https://raw.githubusercontent.com/nextcloud/server/v35.0.0/lib/public/Notification/. The parent interfaces live in
 * the same directory, so the inherited members are part of the surface.
 */

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\NextcloudApiUsage;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

require __DIR__ . '/../../../vendor/autoload.php';

[, $major, $tree] = $argv + [null, null, null];
$server = NextcloudApiUsage::SOURCES[$major]['server'] ?? null;
if ($server === null || $tree === null || !is_file($tree . '/lib/public/Notification/IManager.php')) {
	fwrite(STDERR, "usage: php generate-notification-manager.php <major of NextcloudApiUsage::SOURCES> <tree>\n");
	exit(2);
}
$class = 'OCP\\Notification\\IManager';
$surface = (new SourceParser($tree))->surface($class);
if ($surface === null || !isset($surface['methods']['defer'], $surface['methods']['flush'])) {
	throw new RuntimeException('The tree lacks ' . $class . ' with defer() and flush()');
}
$path = __DIR__ . '/' . $major . '.php';
$fixture = require $path;
$fixture['classes'][$class] = $surface;
ksort($fixture['classes']);
$original = file_get_contents($path);
$header = substr($original, 0, strpos($original, 'return ['));
$header = preg_replace('~// Notification manager surface generated[^\n]*\n~', '', $header);
$header .= '// Notification manager surface generated by generate-notification-manager.php from nextcloud/server v' . $server
	. ' lib/public/Notification (IManager.php sha256 ' . hash_file('sha256', $tree . '/lib/public/Notification/IManager.php') . ").\n";
FixtureFile::write($path, $header, $fixture);
echo 'Added ' . $class . ' to NC' . $major . "\n";
